en.value:
&lt;p&gt;The Correct answer is &lt;strong&gt;&amp;quot;&lt;span style=&quot;&quot;&gt;Ctrl + Z&amp;quot;.&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/important-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Important Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;Undo&lt;/span&gt;&amp;nbsp;functions is the&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;CTRL+Z&lt;/span&gt;&amp;nbsp;command given in MS-Office.&lt;/li&gt;
	&lt;li&gt;Undo helps&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;erase the last changes done&amp;nbsp;&lt;/span&gt;to a particular document and takes you back to its older state.&lt;/li&gt;
	&lt;li&gt;However, there are some actions that you can&amp;#39;t undo such as saving a file.&lt;/li&gt;
&lt;/ul&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;Most programs that support&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;Ctrl+Z&amp;nbsp;&lt;/span&gt;also support the ability to undo&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;multiple changes&lt;/span&gt;. For example, you can press and hold Ctrl, and while still holding the key, press &amp;quot;Z&amp;quot; three times to undo the last three changes.&lt;/li&gt;
	&lt;li&gt;The opposite shortcut key of Ctrl+Z is&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;Ctrl+Y&amp;nbsp;(redo)&lt;/span&gt;.&lt;/li&gt;
	&lt;li&gt;On&amp;nbsp;Apple&amp;nbsp;computers, the shortcut to undo is the&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;Command key+Z&lt;/span&gt;&amp;nbsp;keys.&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;सही उत्तर &lt;strong&gt;&amp;quot; &lt;span style=&quot;&quot;&gt;Ctrl + Z&amp;quot; है।&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/important-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Important Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;अन्डू करने के लिए&amp;nbsp;MS-Office में दिया गया &lt;span style=&quot;font-weight: 700;&quot;&gt;CTRL+Z&lt;/span&gt; कमांड है।&lt;/li&gt;
	&lt;li&gt;अन्डू करें किसी विशेष दस्तावेज़ में &lt;span style=&quot;font-weight: 700;&quot;&gt;किए गए अंतिम परिवर्तनों को मिटाने में&lt;/span&gt; मदद करता है और आपको अपनी पुरानी स्थिति में वापस ले जाता है।&lt;/li&gt;
	&lt;li&gt;हालांकि, कुछ ऐसी कार्य हैं जिन्हें आप अन्डू&amp;nbsp;नहीं कर सकते जैसे किसी फ़ाइल को सहेजना।&lt;/li&gt;
&lt;/ul&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;अधिकांश प्रोग्राम जो &lt;span style=&quot;font-weight: 700;&quot;&gt;Ctrl+Z&lt;/span&gt;&amp;nbsp;का समर्थन करते हैं, &lt;span style=&quot;font-weight: 700;&quot;&gt;अनेक परिवर्तनों&lt;/span&gt; को अन्डू&amp;nbsp;करने की क्षमता का भी समर्थन करते हैं। उदाहरण के लिए, आप Ctrl दबाकर रख सकते हैं, और&amp;nbsp;कंप्युटर&amp;nbsp;की को दबाए रखते हुए, पिछले तीन परिवर्तनों को पूर्ववत करने के लिए &amp;quot;Z&amp;quot; को तीन बार दबाएं।&lt;/li&gt;
	&lt;li&gt;Ctrl+Z की विपरीत शॉर्टकट कंप्युटर की&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;Ctrl+&lt;strong&gt;Y&amp;nbsp;&lt;/strong&gt;&lt;/span&gt;&lt;strong&gt;(रीडू&lt;span style=&quot;font-weight: 700;&quot;&gt; )&lt;/span&gt; &lt;/strong&gt;है।&lt;/li&gt;
	&lt;li&gt;Apple कंप्यूटर पर, अन्डू&amp;nbsp;करने का शॉर्टकट &lt;span style=&quot;font-weight: 700;&quot;&gt;कमांड &lt;/span&gt;&amp;nbsp;&lt;strong&gt;की&lt;/strong&gt;&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;+ Z&lt;/span&gt;&lt;strong&gt;&amp;nbsp;की&lt;/strong&gt;&amp;nbsp;है।&lt;/li&gt;
&lt;/ul&gt;

